package com.contextgraph.service; import com.contextgraph.dto.AuthDtos; import com.contextgraph.model.User; import com.contextgraph.repository.UserRepository; import com.contextgraph.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; @Service public class AuthService{final UserRepository users;final PasswordEncoder encoder;final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public AuthDtos.AuthResponse register(AuthDtos.RegisterRequest r){if(users.existsByEmailIgnoreCase(r.email()))throw new IllegalArgumentException("An account with this email already exists.");User u=new User();u.setName(r.name().trim());u.setEmail(r.email().trim().toLowerCase());u.setPasswordHash(encoder.encode(r.password()));u=users.save(u);return new AuthDtos.AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail());} public AuthDtos.AuthResponse login(AuthDtos.LoginRequest r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Invalid email or password."));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Invalid email or password.");return new AuthDtos.AuthResponse(jwt.generate(u.getEmail()),u.getId(),u.getName(),u.getEmail());}}